#!/bin/sh
set -eu
package_dir=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
build_dir=$(mktemp -d "${TMPDIR:-/tmp}/awc-native-views.XXXXXX")
trap 'rm -rf "$build_dir"' EXIT HUP INT TERM
# Optional SwiftPM flags, such as --scratch-path, are forwarded unchanged.
swift build --package-path "$package_dir" "$@"
library_dir=$(swift build --package-path "$package_dir" --show-bin-path "$@")
# Reuse the compiler's content-keyed module cache across focused runs. Test
# executables remain isolated; the cache lives only in ignored build output.
module_cache_dir=${AWC_NATIVE_TEST_MODULE_CACHE:-"$package_dir/.build/native-view-module-cache"}
mkdir -p "$module_cache_dir"
# Optional focused runs keep the same checked-in compile/runtime path as the full suite.
for fixture in ${AWC_NATIVE_VIEW_FIXTURES:-NativeAppBarStatesIntegration NativeAppBarPaintIntegration NativeNavigationRailStatesIntegration NativeNavigationRailPaintIntegration NativeNavigationRailMembersIntegration NativeCursorHiddenIntegration NativeForcedAppearanceIntegration NativeContainerAccessibilityIntegration NativeToolbarStatesIntegration NativeToolbarPaintIntegration NativeMenuStatesIntegration NativeMenuPaintIntegration NativeMenuVirtualIntegration NativeSelectPaintIntegration NativeSelectStatesIntegration NativeMultiSelectPaintIntegration NativeMultiSelectStatesIntegration NativeBehaviorViewIntegration NativeNavigationBarStatesIntegration NativeNavigationBarPaintIntegration NativeTabsStatesIntegration NativeTabsPaintIntegration NativeBreadcrumbsStatesIntegration NativeBreadcrumbsPaintIntegration NativeSliderRatingIntegration NativeStepperIntegration NativeFaViewsIntegration NativeRippleIntegration NativeFocusViewIntegration NativeButtonAppearanceViewIntegration NativeInspectionViewIntegration NativeIconButtonViewIntegration NativeButtonGroupViewIntegration NativeFabViewIntegration NativeFabMenuLifecycleIntegration NativeFabMenuViewIntegration NativeSegmentedViewIntegration NativeSplitButtonViewIntegration NativeLoadingIndicatorViewIntegration NativeMeterViewIntegration NativeProgressIndicatorViewIntegration NativeSkeletonViewIntegration NativeSnackbarControllerIntegration NativeSnackbarViewIntegration NativeTooltipControllerIntegration NativeTooltipViewIntegration NativeAccordionStateIntegration NativeAccordionBrowserStateIntegration NativeAccordionMotionIntegration NativeAccordionRendererIntegration NativeAccordionInitializationIntegration NativeAccordionScrollingIntegration NativeAccordionAppearanceIntegration NativeAccordionPartsIntegration NativeAccordionReorderIntegration NativeAccordionLiftIntegration NativeAccordionShiftIntegration NativeAccordionStatesIntegration NativeAccordionPlaceholderIntegration NativeAccordionFloatingIntegration NativeCardPaintIntegration NativeCardStatesIntegration NativeCardLifecycleIntegration NativeListMethodsIntegration NativeListRovingIntegration NativeListPartsIntegration NativeStackingIntegration NativeStackingOverlayIntegration NativeListPaintIntegration NativeListStatesIntegration NativeListTooltipIntegration NativeBottomSheetMotionIntegration NativeBottomSheetPaintIntegration NativeDialogMotionIntegration NativeDialogPaintIntegration NativeModalStackIntegration NativeSideSheetMotionIntegration NativeSideSheetPaintIntegration NativeAvatarIntegration NativeSwitchPaintIntegration NativeSwitchStatesIntegration NativeCheckboxPaintIntegration NativeCheckboxStatesIntegration NativeChipPaintIntegration NativeChipStatesIntegration NativeButtonPaintIntegration NativeButtonStatesIntegration NativeButtonFamilyPaintIntegration NativeButtonFamilyStatesIntegration NativeRadioPaintIntegration NativeRadioStatesIntegration NativeTextFieldPaintIntegration NativeTextFieldStatesIntegration NativeNumberFieldPaintIntegration NativeNumberFieldStatesIntegration NativeOTPFieldPaintIntegration NativeOTPFieldStatesIntegration NativeOrgChartPaintIntegration NativeOrgChartStatesIntegration NativeTablePaintIntegration NativeTableStatesIntegration NativeChartSceneIntegration NativeChartInteractionIntegration NativeChartMotionIntegration NativeChartViewsSmoke NativeChartPaintIntegration NativeAutocompleteLifecycleIntegration NativeAutocompletePaintIntegration NativeAutocompleteStatesIntegration NativeDatePickerPaintIntegration NativeDatePickerStatesIntegration NativeTransferListPaintIntegration NativeTransferListStatesIntegration NativeSearchPaintIntegration NativeSearchStatesIntegration NativeThemeIntegration}; do
  case "$fixture" in
    NativeCursorHiddenIntegration|NativeAvatarLazyIntegration|NativeForcedAppearanceIntegration|NativeContainerAccessibilityIntegration|NativeColorPickerPaintIntegration|NativeColorPickerStatesIntegration|NativeTimePickerPaintIntegration|NativeTimePickerStatesIntegration|NativeRippleIntegration|NativeBreadcrumbsPaintIntegration|NativeBreadcrumbsStatesIntegration|NativeSliderRatingIntegration|NativeStepperIntegration|NativeFaViewsIntegration|NativeTabsPaintIntegration|NativeTabsStatesIntegration|NativeNavigationBarPaintIntegration|NativeNavigationBarStatesIntegration|NativeMenuPaintIntegration|NativeMenuStatesIntegration|NativeMenuVirtualIntegration|NativeSelectPaintIntegration|NativeSelectStatesIntegration|NativeMultiSelectPaintIntegration|NativeMultiSelectStatesIntegration|NativeToolbarPaintIntegration|NativeToolbarStatesIntegration|NativeNavigationRailPaintIntegration|NativeNavigationRailMembersIntegration|NativeNavigationRailStatesIntegration|NativeAppBarPaintIntegration|NativeAppBarStatesIntegration|NativeBehaviorViewIntegration|NativeFocusViewIntegration|NativeButtonAppearanceViewIntegration|NativeInspectionViewIntegration|NativeIconButtonViewIntegration|NativeButtonGroupViewIntegration|NativeFabViewIntegration|NativeFabMenuLifecycleIntegration|NativeFabMenuViewIntegration|NativeSegmentedViewIntegration|NativeSplitButtonViewIntegration|NativeLoadingIndicatorViewIntegration|NativeMeterViewIntegration|NativeProgressIndicatorViewIntegration|NativeSkeletonViewIntegration|NativeSnackbarControllerIntegration|NativeSnackbarViewIntegration|NativeTooltipControllerIntegration|NativeTooltipViewIntegration|NativeAccordionStateIntegration|NativeAccordionBrowserStateIntegration|NativeAccordionMotionIntegration|NativeAccordionRendererIntegration|NativeAccordionInitializationIntegration|NativeAccordionScrollingIntegration|NativeAccordionAppearanceIntegration|NativeAccordionPartsIntegration|NativeAccordionReorderIntegration|NativeAccordionLiftIntegration|NativeAccordionShiftIntegration|NativeAccordionStatesIntegration|NativeAccordionPlaceholderIntegration|NativeAccordionFloatingIntegration|NativeCardPaintIntegration|NativeCardStatesIntegration|NativeCardLifecycleIntegration|NativeListMethodsIntegration|NativeListRovingIntegration|NativeListPartsIntegration|NativeStackingIntegration|NativeStackingOverlayIntegration|NativeListPaintIntegration|NativeListStatesIntegration|NativeListTooltipIntegration|NativeBottomSheetMotionIntegration|NativeBottomSheetPaintIntegration|NativeDialogMotionIntegration|NativeDialogPaintIntegration|NativeModalStackIntegration|NativeSideSheetMotionIntegration|NativeSideSheetPaintIntegration|NativeAvatarIntegration|NativeSwitchPaintIntegration|NativeSwitchStatesIntegration|NativeCheckboxPaintIntegration|NativeCheckboxStatesIntegration|NativeChipPaintIntegration|NativeChipStatesIntegration|NativeButtonPaintIntegration|NativeButtonStatesIntegration|NativeButtonFamilyPaintIntegration|NativeButtonFamilyStatesIntegration|NativeRadioPaintIntegration|NativeRadioStatesIntegration|NativeTextFieldPaintIntegration|NativeTextFieldStatesIntegration|NativeNumberFieldPaintIntegration|NativeNumberFieldStatesIntegration|NativeOTPFieldPaintIntegration|NativeOTPFieldStatesIntegration|NativeOrgChartPaintIntegration|NativeOrgChartStatesIntegration|NativeTablePaintIntegration|NativeTableStatesIntegration|NativeChartSceneIntegration|NativeChartInteractionIntegration|NativeChartMotionIntegration|NativeChartViewsSmoke|NativeChartPaintIntegration|NativeAutocompleteLifecycleIntegration|NativeAutocompletePaintIntegration|NativeAutocompleteStatesIntegration|NativeDatePickerPaintIntegration|NativeDatePickerStatesIntegration|NativeTransferListPaintIntegration|NativeTransferListStatesIntegration|NativeSearchPaintIntegration|NativeSearchStatesIntegration|NativeThemeIntegration) ;;
    *) echo "Unknown native view fixture: $fixture" >&2; exit 1 ;;
  esac
  swiftc -parse-as-library -module-cache-path "$module_cache_dir" \
    -I "$library_dir/Modules" "$package_dir/Tests/$fixture.swift" \
    "$library_dir"/AWCUI.build/*.o -o "$build_dir/$fixture"
  # The user may have a mouse connected: AppKit then uses the always-visible legacy scroller (15 px) and every scroll-view suite is off by 15 px. Pin the overlay style for the test process only; an explicit AWC_FIXTURE_ARGS (even empty) overrides.
  fixture_default='-AppleShowScrollBars WhenScrolling'
  # These fixtures read positional arguments (oracle directories): the pin would be taken as a path, so they get no default pin (none of them has a scroll view).
  case "$fixture" in NativeFaViewsIntegration|NativeChartSceneIntegration|NativeChartInteractionIntegration) fixture_default= ;; esac
  fixture_args=${AWC_FIXTURE_ARGS-$fixture_default}
  "$build_dir/$fixture" $fixture_args
  if [ "$fixture" = NativeFabMenuViewIntegration ]; then
    "$build_dir/$fixture" --interactions-only --native-pointer $fixture_args
  fi
done
